 rows(){const map=new Map(Cloud.summaries.map(r=>[r.UUID,{id:r.UUID,kind:r.Actividad,system:r.Sistema,project:r.Proyecto,location:r.Ubicación,date:String(r.Fecha).slice(0,10),state:r.Estado,title:r.Consecutivo,responsible:r.Responsable,email:r.Correo,central:true,url:r.Documento,version:r.Versión}]));for(const r of [...Dash.legacy,...Portal.records]){if(!map.has(r.id))map.set(r.id,{...r,title:r.code||r.title||'Sin consecutivo',responsible:r.responsible||r.inspectorNombre||Portal.person,email:r._cloudOwner||'',central:!!r._cloudVersion});}return [...map.values()].filter(r=>r.state!=='Eliminado').map(r=>{let w;try{w=isoWeek(r.date);}catch{}return {...r,week:w?w.year+'-W'+String(w.week).padStart(2,'0'):'Sin fecha',month:r.date?.slice(0,7)||'Sin fecha'};});},
 nav(){const active=this.selected();const item=(key,label,action,attr='')=>'<button class="side-link '+(active===key?'active':'')+'" data-v3="'+action+'" '+attr+' title="'+esc(label)+'" '+(active===key?'aria-current="page"':'')+'>'+ico(key)+'<span>'+esc(label)+'</span></button>';return '<div class="side-shade '+(this.drawer?'open':'')+'" data-v3="drawer-close"></div><aside class="workspace-side '+(this.drawer?'open':'')+' '+(this.collapsed?'compact':'')+'" aria-label="Navegación principal"><div class="side-brand"><img src="'+APP_ICON+'" alt=""><div><b>SOF-CAL</b><small>Gerencia de Calidad</small></div><button class="icon-button mobile-only" data-v3="drawer-close" aria-label="Cerrar menú">'+ico('close')+'</button></div><nav>'+item('home','Indicadores','home')+item('history','Registros','records')+'<p class="side-label">FUNCIONES</p>'+ACTIVITIES.filter(x=>Portal.can(x[0])).map(([k,,l])=>item(k,l,'nav-function','data-kind="'+k+'"')).join('')+'<p class="side-label">SOPORTE</p>'+item('help','Ayuda','help')+(Portal.role==='admin'?item('settings','Ajustes','settings'):'')+'</nav><div class="side-footer"><div class="user-avatar">'+esc((Portal.person||'U').slice(0,1))+'</div><div><b>'+esc(Portal.person)+'</b><small>'+esc(Portal.role)+'</small></div><button class="icon-button" data-v3="logout" title="Cerrar sesión">'+ico('logout')+'</button></div></aside>';},
