const experienceInput=V3Events.input.bind(V3Events);V3Events.input=function(t){const r=Portal.record;if(r&&!Workspace.editable(r))return;experienceInput(t);if(t.dataset.v3Field==='system'&&r){AutoProject.apply(r);const el=document.querySelector('[data-auto-project]');if(el)el.textContent=r.project||'Sistema sin proyecto configurado';}};
