Portal.shell=body=>Workspace.frame(body);Portal.homeView=()=>Workspace.dashboard();
Portal.open=async function(id){await this.flush();const r=this.records.find(x=>x.id===id);if(!r)throw Error('Registro no encontrado.');this.record=clone(r);this.record._readOnly=!Workspace.editable(r);this.page=['rayado','sensibilizacion','permiso','rca'].includes(r.kind)?r.kind:r.kind==='nc'?'nc-edit':'form';this.category=r.kind;App.view='portal';FormEditor.page=0;FormEditor.tab='datos';render();};
