const Login={busy:false,stage:'',slow:false,timer:null,redirectTimer:null,
 start(stage){this.busy=true;this.stage=stage;this.slow=false;clearTimeout(this.timer);this.timer=setTimeout(()=>{this.slow=true;this.paint();},15000);this.paint();},
 finish(){this.busy=false;clearTimeout(this.timer);clearTimeout(this.redirectTimer);this.paint();},
 paint(){document.querySelectorAll('[data-v3="google-login"]').forEach(button=>{button.disabled=this.busy;button.setAttribute('aria-busy',String(this.busy));button.innerHTML='<span class="google-g">G</span>'+(this.busy?'Conectando…':'Continuar con Google');});let el=document.getElementById('login-progress');if(!this.busy){el?.remove();return;}if(!el){el=document.createElement('div');el.id='login-progress';el.setAttribute('role','status');el.setAttribute('aria-live','polite');document.body.append(el);}el.innerHTML='<div class="loading-card"><img src="'+APP_ICON+'" alt=""><div class="loading-spinner"></div><h2>'+esc(this.stage)+'</h2><p>'+esc(this.slow?'La conexión está tardando más de lo habitual. Espera a que termine; no necesitas volver a pulsar Ingresar.':'Estamos preparando tu espacio de trabajo. Esto puede tardar unos segundos.')+'</p></div>';}
};
Cloud.loginView=function(){return '<main class="login-layout"><section class="login-visual"><img class="login-art" src="'+EXPERIENCE_ART+'" alt="Ilustración de ingeniería y control de calidad"><div><span class="eyebrow">GERENCIA DE CALIDAD</span><h2>Construimos confianza.<br>Registramos calidad.</h2><p>Inspecciones, documentos y seguimiento del equipo en un solo lugar.</p></div></section><section class="login-form"><img class="login-company" src="'+SA.logo+'" alt="SOFRATESA"><span class="eyebrow">BIENVENIDO A TU ESPACIO</span><h1>SOF-CAL</h1><p>Ingresa con tu Gmail autorizado para continuar.</p><button class="btn pri login-google" data-v3="google-login" '+(Login.busy?'disabled aria-busy="true"':'')+'><span class="google-g">G</span>'+esc(Login.busy?'Conectando…':'Continuar con Google')+'</button>'+(this.error?'<div class="note warn" role="alert">'+esc(this.error)+'</div>':'')+'<div class="login-assurance">'+ico('liberacion')+'<span>Acceso por perfil.<br>Tu contraseña se introduce únicamente en Google.</span></div><button class="text-button" data-v3="google-config">Configuración del administrador</button><small class="login-version">SOF-CAL 4.0.2 · Gerencia de Calidad</small></section></main>';};
const previousLogin=Cloud.login.bind(Cloud);Cloud.login=async function(){if(Login.busy)return;this.error='';Login.start('Conectando con Google');try{await new Promise(resolve=>setTimeout(resolve,50));await previousLogin();Login.redirectTimer=setTimeout(()=>{Login.finish();this.error='No se completó la apertura de Google. Comprueba tu conexión y vuelve a pulsar Continuar con Google.';render();},45000);}catch(e){Login.finish();this.error=errMsg(e);render();throw e;}};
Cloud.init=async function(){Login.start('Preparando SOF-CAL');try{this.config=(await Store.get('meta','google-config'))?.value||DEFAULT_GOOGLE;if(this.config.endpoint?.trim()==='https://script.google.com/macros/s/AKfycbxl61W0ql8do1Xo-QkcBsfFVH02vKlX8irYLbfwdxC-Gon5ccfL1TYEUc_fTfuT4SgW/exec'){this.config={...this.config,endpoint:DEFAULT_GOOGLE.endpoint};this.session=null;sessionStorage.removeItem('sofcal-google-session');}await Store.put('meta',{k:'google-config',value:this.config});Schema.fields=(await Store.get('meta','capture-schema'))?.value||[];const hash=new URLSearchParams(location.hash.slice(1));if(hash.has('sofcal_session')){const state=sessionStorage.getItem('sofcal-oauth-state');history.replaceState(null,'',location.pathname+location.search);if(!state||hash.get('state')!==state)throw Error('El acceso no corresponde a este navegador. Inicia sesión de nuevo.');sessionStorage.removeItem('sofcal-oauth-state');this.session=hash.get('sofcal_session');sessionStorage.setItem('sofcal-google-session',this.session);}else this.session=sessionStorage.getItem('sofcal-google-session');
 if(this.session){Login.stage='Verificando tu acceso';Login.paint();const data=await this.api('me');this.user=data.user;this.serverVersion=data.serverVersion||'3';if(!String(this.serverVersion).startsWith('4'))throw Error('El servidor de Google requiere la actualización 4.0. Administración debe publicar Code.gs, Administration.gs y Dashboard.gs.');this.config.sheetURL=data.sheetURL;this.applyUser();Login.stage='Cargando registros y configuración';Login.paint();await this.catalog();await this.refresh();await Portal.home();}else render();
 }catch(e){this.error=errMsg(e);this.user=null;Portal.role=null;Session.admin=false;render();}finally{Login.finish();document.getElementById('startup-screen')?.remove();}
 clearInterval(this.poller);this.poller=setInterval(()=>{if(this.user&&document.visibilityState==='visible'&&navigator.onLine)this.sync().then(()=>this.refresh()).catch(e=>{this.error=errMsg(e);this.badge();});},30000);if(!this.onlineBound){window.addEventListener('online',()=>{if(this.user)this.sync().catch(()=>{});});this.onlineBound=true;}if(this.user)await Portal.remindDrafts();};
window.addEventListener('pageshow',e=>{if(e.persisted){Login.finish();render();}});
const originalCatalog4=Cloud.catalog.bind(Cloud);Cloud.catalog=async function(write){await originalCatalog4(write);if(!write)await Dash.load();};
const queue4=Cloud.queue.bind(Cloud);Cloud.queue=async function(r,legacy=false){if(!this.user||Workspace.exporting)return;if(this.user.role!=='admin'&&!r._submitRequested)return;if(this.user.role!=='admin'&&r._cloudVersion)return;return queue4(r,legacy);};
const send4=Cloud.sendRecord.bind(Cloud);Cloud.sendRecord=async function(r,legacy,requestId,importExisting){if(!legacy)AutoProject.check(r);else AutoProject.apply(r);const result=await send4(r,legacy,requestId,importExisting);if(result.project){if(legacy)r.datos.proyecto=result.project;else r.project=result.project;}if(this.user?.role!=='admin'){delete r._submitRequested;if(Portal.record?.id===r.id)Portal.record._readOnly=true;}return result;};
const upload4=Cloud.upload.bind(Cloud);Cloud.upload=async function(r,blob,name){await upload4(r,blob,name);};
