const badge4=Cloud.badge.bind(Cloud);Cloud.badge=function(){badge4();const el=document.getElementById('workspace-connection');if(el)el.innerHTML=(this.busy?'<i class="tiny-spinner"></i>':'<i></i>')+esc(!navigator.onLine?'Sin conexión':this.busy?'Sincronizando':this.error?'Revisar sincronización':'Conectado');};
const api4=Cloud.api.bind(Cloud);Cloud.api=async function(action,payload){const data=await api4(action,payload);if(action==='list'){if(data.user){this.user=data.user;this.applyUser();}if(data.factoryEpoch&&data.factoryEpoch!==(await Store.get('meta','factory-epoch'))?.value){await Settings.resetLocalConfiguration();await Store.put('meta',{k:'factory-epoch',value:data.factoryEpoch});}for(const job of data.maintenance||[])await Settings.applyRecordRemoval(job.scope,job.at);}return data;};
// Read-only downloads never enqueue new versions. Original uploaded documents remain accessible.
const download4=Cloud.download.bind(Cloud);Cloud.download=async function(id){await Portal.flush();if(App.insp)await saveNow();await download4(id);if(Portal.record)Portal.record._readOnly=!Workspace.editable(Portal.record);render();};
const safeActions=new Set(['form-tab','page-next','page-prev','goto-page','zoom-in','zoom-out','tool','rca-tab','view-file','settings','help','drawer-toggle','drawer-close','nav-function','home','functions','records','person-filter','workspace-search','records-kind','dashboard-refresh','all-filters-clear','dashboard-group','open','google-download','logout','legacy-open','record-download']);
const action4=V3Events.action.bind(V3Events);V3Events.action=async function(b,e){const a=b.dataset.v3,r=Portal.record;if(r&&!Workspace.editable(r)&&!safeActions.has(a)&&!a.startsWith('settings-'))throw Error('Este registro es de consulta. Solo el administrador puede modificarlo.');
 switch(a){case'drawer-toggle':if(matchMedia('(max-width: 900px)').matches)Workspace.drawer=!Workspace.drawer;else Workspace.collapsed=!Workspace.collapsed;Workspace.mountNav();return;case'drawer-close':Workspace.drawer=false;Workspace.mountNav();return;case'nav-function':return Portal.activity(b.dataset.kind);case'settings':await Settings.open();return;case'person-filter':return Workspace.personFilter();case'records':await Portal.history();return;case'records-kind':Workspace.kind=b.dataset.kind;render();return;case'workspace-search':Workspace.q=document.getElementById('workspace-search').value;render();return;case'all-filters-clear':Dash.filters={};Workspace.person='';render();return;case'record-download':{const row=Cloud.summaries.find(x=>x.UUID===(r?.id||App.insp?.uuid));if(row?.Documento)window.open(safeURL(row.Documento),'_blank','noopener');else throw Error('Este registro aún no tiene un documento central.');return;}case'register-record':if(!r)return;AutoProject.check(r);r._submitRequested=true;await Portal.save();await Cloud.sync();if(Cloud.error)throw Error(Cloud.error);await Cloud.refresh();render();return;}
 if(['record-pdf','record-final','simple-pdf','simple-final','nc-word','rca-xlsx'].includes(a)&&r){AutoProject.check(r);Workspace.exporting=true;try{await action4(b,e);}catch(err){delete r._submitRequested;throw err;}finally{Workspace.exporting=false;}r._submitRequested=true;await Portal.save();await Cloud.sync();await Cloud.refresh();render();return;}
 if(['home','functions','help','records'].includes(a)){await Portal.flush();if(App.insp)await saveNow();Portal.record=null;Workspace.drawer=false;}
 return action4(b,e);};
const inputProtected4=V3Events.input.bind(V3Events);V3Events.input=t=>{if(Portal.record&&!Workspace.editable(Portal.record))return;inputProtected4(t);};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&Workspace.drawer){Workspace.drawer=false;Workspace.mountNav();}if(e.key==='Enter'&&e.target.id==='workspace-search'){Workspace.q=e.target.value;render();}});
Workspace.mountNav=function(){let el=document.getElementById('workspace-nav');if(!Portal.role){el?.remove();return;}if(!el){el=document.createElement('div');el.id='workspace-nav';document.body.append(el);}el.innerHTML=this.nav();document.body.classList.toggle('sidebar-compact',this.collapsed);document.body.classList.toggle('drawer-open',this.drawer);};
const render4=render;render=function(){render4();document.body.classList.toggle('experience-session',!!Portal.role);document.body.classList.toggle('experience-login',!Portal.role);document.getElementById('startup-screen')?.remove();if(Portal.role&&App.view!=='portal'){const v=document.getElementById('view');const body=v.innerHTML;v.innerHTML=Workspace.frame(body);}
 Workspace.mountNav();const r=App.view==='portal'?Portal.record:App.insp;if(r&&!Workspace.editable(r)){document.querySelectorAll('#view input,#view select,#view textarea').forEach(el=>el.disabled=true);document.querySelectorAll('#view [data-v3]').forEach(b=>{if(!safeActions.has(b.dataset.v3))b.hidden=true;});document.querySelectorAll('#view [data-act],#view [data-sf]').forEach(b=>{const a=b.dataset.act||b.dataset.sf;if(!['review','review-result','jump','hist-open'].includes(a))b.hidden=true;});const target=document.querySelector('.workspace-content')||document.getElementById('view');target.insertAdjacentHTML('afterbegin','<div class="read-only-banner">'+ico('liberacion')+'<span>Registro central · solo consulta. Las modificaciones las realiza el administrador.</span>'+richButton('Documento emitido','record-download','documentos')+'</div>');}
 else if(r&&App.view==='portal'&&!r._cloudVersion){document.querySelector('.v3-record-head>div:last-child')?.insertAdjacentHTML('beforeend',vb('Registrar en la base central','register-record'));document.querySelector('.v3-record-head')?.insertAdjacentHTML('afterend','<p class="capture-note">Borrador local: puedes completarlo antes de registrar. Al enviarlo a la base central, las modificaciones quedan reservadas al administrador.</p>');}
 if(Portal.role!=='admin')document.querySelectorAll('[data-go="admin"],[data-v3="legacy-admin"],[data-v3^="schema-"]').forEach(b=>b.hidden=true);Login.paint();};
// Preserve historic linked documents in storage, but do not display/edit them in inspection closure.
const oldInspectionExport4=Sofcal.saveAndQueue.bind(Sofcal);Sofcal.saveAndQueue=async function(i,download){if(!Workspace.editable(i))throw Error('Descargue el documento emitido desde Registros. Solo Administración puede modificar esta ficha.');Workspace.exporting=true;try{await oldInspectionExport4(i,download);}finally{Workspace.exporting=false;}i._submitRequested=true;await Insp.save(i);await Cloud.queue(i,true);await Cloud.sync();};
const oldInspSave4=Insp.save.bind(Insp);Insp.save=async function(i){if(!Workspace.editable(i))return;return oldInspSave4(i);};

const syncExperience=Cloud.sync.bind(Cloud);Cloud.sync=async function(){const before=Portal.record?._cloudVersion;await syncExperience();if(Portal.record&&!before&&Portal.record._cloudVersion&&Portal.role!=='admin')render();};
